00033 if (!function_exists('wb_create_control')) {
00034     function wb_create_control($parent, $class, $caption = "", $xpos = 0, $ypos = 0, $width = 0, $height = 0, $id = null, $style = 0, $lparam = null, $ntab = 0)
00035     {
00036         switch ($class) {
00037             case Accel:
00038                 return wbtemp_set_accel_table($parent, $caption);
00039 
00040             case ToolBar:
00041                 return wbtemp_create_toolbar($parent, $caption, $width, $height, $lparam);
00042 
00043             case Menu:
00044                 return wbtemp_create_menu($parent, $caption);
00045 
00046             case HyperLink:
00047                 return wbtemp_create_control(
00048                     $parent,
00049                     $class,
00050                     $caption,
00051                     $xpos,
00052                     $ypos,
00053                     $width,
00054                     $height,
00055                     $id,
00056                     $style,
00057                     is_null($lparam) ? NOCOLOR : $lparam,
00058                     $ntab
00059                 );
00060 
00061             case ComboBox:
00062             case ListBox:
00063             case ListView:
00064                 $ctrl = wbtemp_create_control($parent, $class, $caption, $xpos, $ypos, $width, $height, $id, $style, $lparam, $ntab);
00065                 if (is_array($caption)) {
00066                     wb_set_text($ctrl, $caption[0]);
00067                 }
00068 
00069                 return $ctrl;
00070 
00071             case TreeView:
00072                 $ctrl = wbtemp_create_control($parent, $class, $caption, $xpos, $ypos, $width, $height, $id, $style, $lparam, $ntab);
00073                 if (is_array($caption)) {
00074                     wb_set_text($ctrl, $caption[0]);
00075                 }
00076 
00077                 return $ctrl;
00078 
00079             case Gauge:
00080             case Slider:
00081             case ScrollBar:
00082                 $ctrl = wbtemp_create_control($parent, $class, $caption, $xpos, $ypos, $width, $height, $id, $style, $lparam, $ntab);
00083                 if ($lparam) {
00084                     wb_set_value($ctrl, $lparam);
00085                 }
00086 
00087                 return $ctrl;
00088 
00089             default:
00090                 return wbtemp_create_control($parent, $class, $caption, $xpos, $ypos, $width, $height, $id, $style, $lparam, $ntab);
00091         }
00092     }
00093 }
