00104 if (!function_exists('wb_set_value')) {
00105     function wb_set_value($ctrl, $value, $item = null)
00106     {
00107         if (!$ctrl) {
00108             return null;
00109         }
00110 
00111         $class = wb_get_class($ctrl);
00112         switch ($class) {
00113             case ListView:        // Array with items to be checked
00114 
00115                 if ($value === null) {
00116                     break;
00117                 } elseif (is_string($value) && strstr($value, ",")) {
00118                     $values = explode(",", $value);
00119                 } elseif (!is_array($value)) {
00120                     $values = array($value);
00121                 } else {
00122                     $values = $value;
00123                 }
00124                 foreach ($values as $index) {
00125                     wbtemp_set_listview_item_checked($ctrl, $index, 1);
00126                 }
00127                 break;
00128 
00129             case TreeView:        // Array with items to be checked
00130 
00131                 if ($item === null) {
00132                     $item = wbtemp_get_selected($ctrl);
00133                 }
00134 
00135                 return wbtemp_set_treeview_item_value($ctrl, $item, $value);
00136 
00137             default:
00138 
00139                 if ($value !== null) {
00140                     return wbtemp_set_value($ctrl, $value, $item);
00141                 }
00142         }
00143     }
00144 }
