00156 if (!function_exists('wb_get_text')) {
00157     function wb_get_text($ctrl, $item = null, $subitem = null)
00158     {
00159         if (!$ctrl) {
00160             return null;
00161         }
00162 
00163         if (wb_get_class($ctrl) == ListView) {
00164             if ($item !== null) {        // Valid item
00165 
00166                 $line = wbtemp_get_listview_text($ctrl, $item);
00167                 if ($subitem === null) {
00168                     return $line;
00169                 } else {
00170                     return $line[$subitem];
00171                 }
00172             } else {                    // NULL item
00173 
00174                 $sel = wb_get_selected($ctrl);
00175                 if ($sel === null) {        // Returns the entire table
00176                     $items = array();
00177                     for ($i = 0; ; $i++) {
00178                         $item = wbtemp_get_listview_text($ctrl, $i);
00179                         $all  = implode('', $item);
00180                         if ($all == '') {
00181                             break;
00182                         }
00183                         $items[] = $item;
00184                     }
00185 
00186                     return $items ? $items : null;
00187                 } else {
00188                     $items = array();
00189                     foreach ($sel as $row) {
00190                         $items[] = wbtemp_get_listview_text($ctrl, $row);
00191                     }
00192 
00193                     return $items ? $items : null;
00194                 }
00195             }
00196         } elseif (wb_get_class($ctrl) == TreeView) {
00197             if ($item) {
00198                 return wbtemp_get_treeview_item_text($ctrl, $item);
00199             } else {
00200                 $sel = wb_get_selected($ctrl);
00201                 if ($sel === null) {
00202                     return null;
00203                 } else {
00204                     return wbtemp_get_text($ctrl);
00205                 }
00206             }
00207         } elseif (wb_get_class($ctrl) == ComboBox) {
00208             return wbtemp_get_text($ctrl, $item === null ? -1 : $item);
00209         } elseif (wb_get_class($ctrl) == ListBox) {
00210             return wbtemp_get_text($ctrl, $item === null ? -1 : $item);
00211         } else {
00212             return wbtemp_get_text($ctrl, $item);
00213         }
00214     }
00215 }
