00230 if (!function_exists('wb_set_text')) {
00231     function wb_set_text($ctrl, $text, $item = null, $subitem = null)
00232     {
00233         if (!$ctrl) {
00234             return null;
00235         }
00236 
00237         switch (wb_get_class($ctrl)) {
00238             case ListView:
00239 
00240                 if ($item !== null) {
00241                     if (!is_array($text) && $subitem !== null) {
00242                         // Set text of a ListView cell according to $item and $subitem
00243 
00244                         wbtemp_set_listview_item_text($ctrl, $item, $subitem, $text);
00245                     } else {
00246                         // Set text of several ListView cells, ignoring $subitem
00247 
00248                         for ($sub = 0; $sub < count($text); $sub++) {
00249                             if ($text) {
00250                                 if (($text[$sub] !== null)) {
00251                                     wbtemp_set_listview_item_text($ctrl, $item, $sub, (string)$text[$sub]);
00252                                 }
00253                             } else {
00254                                 wbtemp_set_listview_item_text($ctrl, $item, $sub, "");
00255                             }
00256                         }
00257                     }
00258                 } else {
00259                     if (!is_array($text)) {
00260                         $text = explode(",", $text);
00261                     }
00262 
00263                     wb_delete_items($ctrl, null);
00264 
00265                     if (!$item) {
00266                         wbtemp_clear_listview_columns($ctrl);
00267 
00268                         // Create column headers
00269                         // In the loop below, passing -1 as the 'width' argument of wbtemp_create_listview_column()
00270                         // makes it calculate the column width automatically
00271 
00272                         for ($i = 0; $i < count($text); $i++) {
00273                             if (is_array($text[$i])) {
00274                                 wbtemp_create_listview_column(
00275                                     $ctrl,
00276                                     $i,
00277                                     (string)$text[$i][0],
00278                                     isset($text[$i][1]) ? (int)$text[$i][1] : -1,
00279                                     isset($text[$i][2]) ? (int)$text[$i][2] : WBC_LEFT
00280                                 );
00281                             } else {
00282                                 wbtemp_create_listview_column(
00283                                     $ctrl,
00284                                     $i,
00285                                     (string)$text[$i],
00286                                     -1,
00287                                     0
00288                                 );
00289                             }
00290                         }
00291                     }
00292                 }
00293                 break;
00294 
00295             case ListBox:
00296 
00297                 if (!$text) {
00298                     wb_delete_items($ctrl);
00299                 } elseif (is_string($text)) {
00300                     if (strchr($text, "\r") || strchr($text, "\n")) {
00301                         $text = preg_split("/[\r\n,]/", $text);
00302                         wb_delete_items($ctrl);
00303                         foreach ($text as $str) {
00304                             wbtemp_create_item($ctrl, (string)$str);
00305                         }
00306                     } else {
00307                         $index = wb_send_message($ctrl, LB_FINDSTRINGEXACT, -1, wb_get_address($text));
00308                         wb_send_message($ctrl, LB_SETCURSEL, $index, 0);
00309                     }
00310                 } elseif (is_array($text)) {
00311                     wb_delete_items($ctrl);
00312                     foreach ($text as $str) {
00313                         wbtemp_create_item($ctrl, (string)$str);
00314                     }
00315                 }
00316 
00317                 return;
00318 
00319             case ComboBox:
00320 
00321                 if (!$text) {
00322                     wb_delete_items($ctrl);
00323                 } elseif (is_string($text)) {
00324                     if (strchr($text, "\r") || strchr($text, "\n")) {
00325                         $text = preg_split("/[\r\n,]/", $text);
00326                         wb_delete_items($ctrl);
00327                         foreach ($text as $str) {
00328                             wbtemp_create_item($ctrl, (string)$str);
00329                         }
00330                     } else {
00331                         $index = wb_send_message($ctrl, CB_FINDSTRINGEXACT, -1, wb_get_address($text));
00332                         wb_send_message($ctrl, CB_SETCURSEL, $index, 0);
00333                         if ($index == -1) {
00334                             wb_send_message($ctrl, WM_SETTEXT, 0, wb_get_address($text));
00335                         }
00336                     }
00337                 } elseif (is_array($text)) {
00338                     wb_delete_items($ctrl);
00339                     foreach ($text as $str) {
00340                         wbtemp_create_item($ctrl, (string)$str);
00341                     }
00342                 }
00343 
00344                 return;
00345 
00346             case TreeView:
00347 
00348                 if ($item) {
00349                     return wbtemp_set_treeview_item_text($ctrl, $item, $text);
00350                 } else {
00351                     return wb_create_items($ctrl, $text, true);
00352                 }
00353 
00354             default:
00355                 // The (string) cast below works well but is a temporary fix, must be
00356                 // removed when wbtemp_set_text() accepts numeric types correctly
00357                 if (is_array($text)) {
00358                     return wbtemp_set_text($ctrl, $text, $item);
00359                 } else {
00360                     return wbtemp_set_text($ctrl, (string)$text, $item);
00361                 }
00362         }
00363     }
00364 }
