00375 if (!function_exists('wb_set_selected')) {
00376     function wb_set_selected($ctrl, $selitems = 0, $selected = true)
00377     {
00378         switch (wb_get_class($ctrl)) {
00379             case ComboBox:
00380                 wb_send_message($ctrl, CB_SETCURSEL, (int)$selitems, 0);
00381                 break;
00382 
00383             case ListBox:
00384                 wb_send_message($ctrl, LB_SETCURSEL, (int)$selitems, 0);
00385                 break;
00386 
00387             case ListView:
00388 
00389                 if (is_null($selitems)) {
00390                     return wbtemp_select_all_listview_items($ctrl, false);
00391                 } elseif (is_array($selitems)) {
00392                     foreach ($selitems as $item) {
00393                         wbtemp_select_listview_item($ctrl, $item, $selected);
00394                     }
00395 
00396                     return true;
00397                 } else {
00398                     return wbtemp_select_listview_item($ctrl, $selitems, $selected);
00399                 }
00400                 break;
00401 
00402             case Menu:
00403                 return wbtemp_set_menu_item_checked($ctrl, $selitems, $selected);
00404 
00405             case TabControl:
00406                 wbtemp_select_tab($ctrl, (int)$selitems);
00407                 break;
00408 
00409             case TreeView:
00410                 wbtemp_set_treeview_item_selected($ctrl, $selitems);
00411                 break;
00412 
00413             default:
00414                 return false;
00415         }
00416 
00417         return true;
00418     }
00419 }
