00431 if (!function_exists('wb_create_items')) {
00432     function wb_create_items($ctrl, $items, $clear = false, $param = null)
00433     {
00434         switch (wb_get_class($ctrl)) {
00435             case ListView:
00436 
00437                 if ($clear) {
00438                     wb_send_message($ctrl, LVM_DELETEALLITEMS, 0, 0);
00439                 }
00440 
00441                 $last = -1;
00442 
00443                 // For each row
00444 
00445                 for ($i = 0; $i < count($items); $i++) {
00446                     if (!is_scalar($items[$i])) {
00447                         $last = wbtemp_create_listview_item(
00448                             $ctrl,
00449                             -1,
00450                             -1,
00451                             (string)$items[$i][0]
00452                         );
00453                     } else {
00454                         $last = wbtemp_create_listview_item(
00455                             $ctrl,
00456                             -1,
00457                             -1,
00458                             (string)$items[$i]
00459                         );
00460                     }
00461                     wbtemp_set_listview_item_text($ctrl, -1, 0, (string)$items[$i][0]);
00462 
00463                     // For each column except the first
00464 
00465                     for ($sub = 0; $sub < count($items[$i]) - 1; $sub++) {
00466                         if ($param) {
00467                             $result = call_user_func(
00468                                 $param,    // Callback function
00469                                 $items[$i][$sub + 1],            // Item value
00470                                 $i,                                // Row
00471                                 $sub                            // Column
00472                             );
00473                             wbtemp_set_listview_item_text($ctrl, $last, $sub + 1, $result);
00474                         } else {
00475                             wbtemp_set_listview_item_text($ctrl, $last, $sub + 1, (string)$items[$i][$sub + 1]);
00476                         }
00477                     }
00478                 }
00479 
00480                 return $last;
00481                 break;
00482 
00483             case TreeView:
00484 
00485                 if ($clear) {
00486                     $handle = wb_delete_items($ctrl);
00487                 } // Empty the treeview
00488 
00489                 if (!$items) {
00490                     break;
00491                 }
00492                 $ret = array();
00493                 for ($i = 0; $i < count($items); $i++) {
00494                     $ret[] = wbtemp_create_treeview_item(
00495                         $ctrl,
00496                         (string)$items[$i][0],                        // Name
00497                         isset($items[$i][1]) ? $items[$i][1] : 0,        // Value
00498                         isset($items[$i][2]) ? $items[$i][2] : 0,        // Where
00499                         isset($items[$i][3]) ? $items[$i][3] : -1,    // ImageIndex
00500                         isset($items[$i][4]) ? $items[$i][4] : -1,    // SelectedImageIndex
00501                         isset($items[$i][5]) ? $items[$i][5] : 0        // InsertionType
00502                     );
00503                 }
00504 
00505                 return (count($ret) > 1 ? $ret : $ret[0]);
00506                 break;
00507 
00508             case StatusBar:
00509                 wbtemp_create_statusbar_items($ctrl, $items, $clear, $param);
00510                 foreach ($items as $item) {
00511                     wb_set_text($ctrl, $item[0], key($item));
00512                 }
00513 
00514                 return true;
00515 
00516             default:
00517 
00518                 if (is_array($items)) {
00519                     foreach ($items as $item) {
00520                         wbtemp_create_item($ctrl, $item);
00521                     }
00522 
00523                     return true;
00524                 } else {
00525                     return wbtemp_create_item($ctrl, $items);
00526                 }
00527                 break;
00528         }
00529     }
00530 }
