00583     if (!function_exists('_make_file_filter')) {
00584         function _make_file_filter($filter)
00585         {
00586             if (!$filter) {
00587                 return "All Files (*.*)\0*.*\0\0";
00588             }
00589 
00590             if (is_array($filter)) {
00591                 $result = "";
00592                 foreach ($filter as $line) {
00593                     $result .= "$line[0] ($line[1])\0$line[1]\0";
00594                 }
00595                 $result .= "\0";
00596 
00597                 return $result;
00598             } else {
00599                 return $filter;
00600             }
00601         }
00602     }
